                        { id: 4, label: "TIER 4: PUBLIC USERS", y: 176, h: 52, wBot: 308, wTop: 236, delay: '0.2s', opacity: 0.25 },
                        { id: 3, label: "TIER 3: CONSUMER", y: 124, h: 52, wBot: 236, wTop: 164, delay: '0.3s', opacity: 0.4 },
                        { id: 2, label: "TIER 2: SOVEREIGN", y: 72, h: 52, wBot: 164, wTop: 92, delay: '0.4s', opacity: 0.6 },
