                                d={`M${200 - tier.wBot/2} ${tier.y + tier.h} L${200 + tier.wBot/2} ${tier.y + tier.h} L${200 + tier.wTop/2} ${tier.y} L${200 - tier.wTop/2} ${tier.y} Z`} 
