export const DroneSwarm = () => {
    const [dots, setDots] = useState<{x: number, y: number, type: 'aligned' | 'unaligned', speedX: number, speedY: number}[]>([]);

    // Simple simulation loop
    useEffect(() => {
        // Init
        const initialDots: {x: number, y: number, type: 'aligned' | 'unaligned', speedX: number, speedY: number}[] = [];
        // Aligned: Cluster in center, slow
        for(let i = 0; i < 15; i++) {
            initialDots.push({
                x: 150 + (Math.random() - 0.5) * 60, 
                y: 100 + (Math.random() - 0.5) * 60, 
                type: 'aligned',
                speedX: (Math.random() - 0.5) * 0.2,
                speedY: (Math.random() - 0.5) * 0.2
            });
        }
        // Unaligned: Spread out, fast
        for(let i = 0; i < 20; i++) {
            initialDots.push({
                x: Math.random() * 300, 
                y: Math.random() * 200, 
                type: 'unaligned',
                speedX: (Math.random() - 0.5) * 2,
                speedY: (Math.random() - 0.5) * 2
            });
        }
        setDots(initialDots);

        const interval = setInterval(() => {
            setDots(prevDots => prevDots.map(dot => {
                let newX = dot.x + dot.speedX;
                let newY = dot.y + dot.speedY;

                // Bounce off walls
                let newSpeedX = dot.speedX;
                let newSpeedY = dot.speedY;

                if (newX <= 0 || newX >= 300) newSpeedX *= -1;
                if (newY <= 0 || newY >= 200) newSpeedY *= -1;

                // Clamp
                newX = Math.max(0, Math.min(300, newX));
                newY = Math.max(0, Math.min(200, newY));

                return { ...dot, x: newX, y: newY, speedX: newSpeedX, speedY: newSpeedY };
            }));
        }, 30);

        return () => clearInterval(interval);
    }, []);

    return (
        <div className={chartContainerClass}>
            <h4 className={captionClass}>Fig 2.4 Swarm Dynamics Simulation</h4>
            <div className="relative w-full max-w-md h-48 bg-[#050505] border border-white/10 rounded-lg overflow-hidden shadow-inner">
                {/* Grid Overlay */}
                <div className="absolute inset-0 opacity-20" 
                     style={{ backgroundImage: 'linear-gradient(rgba(255,255,255,1) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,1) 1px, transparent 1px)', backgroundSize: '20px 20px' }} 
                />

                {/* Radar Scan Effect */}
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent opacity-20 w-full h-full animate-[spin_4s_linear_infinite] origin-bottom-left" />

                <svg className="w-full h-full relative z-10" viewBox="0 0 300 200">
                    {dots.map((d, i) => (
                         <circle 
                            key={i} 
                            cx={d.x} 
                            cy={d.y} 
                            r={d.type === 'aligned' ? 3 : 2} 
                            fill={d.type === 'aligned' ? '#3b82f6' : '#ef4444'}
                            className="transition-all duration-[30ms] ease-linear"
                         />
                    ))}
                </svg>

                <div className="absolute bottom-2 left-2 flex gap-4 text-[9px] font-mono bg-black/50 p-2 rounded backdrop-blur-sm border border-white/10">
                    <div className="flex items-center gap-1 text-blue-400">
                        <div className="w-2 h-2 rounded-full bg-blue-500" /> ALIGNED (Restricted)
                    </div>
                    <div className="flex items-center gap-1 text-red-400">
                        <div className="w-2 h-2 rounded-full bg-red-500" /> UNALIGNED (Optimized)
                    </div>
                </div>
            </div>
        </div>
    );
}

