    DroneSwarm,
    MarketBifurcation
} from '../components/EssayVisuals';

interface PageProps {
    animations: boolean;
    elevation: boolean;
    isCompact: boolean;
    slug: string;
    navigateTo: (route: Route) => void;
    isKonamiActive: boolean;
    setIsKonamiActive: (isActive: boolean) => void;
