}

const KatexRenderer: React.FC<{ expression: string, displayMode?: boolean }> = ({ expression, displayMode = false }) => {
    const containerRef = React.useRef<HTMLSpanElement>(null);

    React.useEffect(() => {
        if (containerRef.current && (window as any).katex) {
            try {
                (window as any).katex.render(expression, containerRef.current, {
                    throwOnError: false,
                    displayMode: displayMode,
                });
            } catch (e) {
                console.error("KaTeX error:", e);
                containerRef.current.innerText = expression;
            }
        }
    }, [expression, displayMode]);

    return <span ref={containerRef} />;
};

const renderFormattedContent = (content: string) => {
  return content.split('\n').map((line, index) => {
    const trimmedLine = line.trim();

    if (trimmedLine === '') {
      return null;
    }

    const key = `${index}-${trimmedLine.substring(0, 20)}`;

    // Custom Component Parsers
    if (trimmedLine === '[[CASTE_PYRAMID]]') return <CastePyramid key={key} />;
    if (trimmedLine === '[[COMPUTE_VELOCITY]]') return <ComputeVelocityGraph key={key} />;
    if (trimmedLine === '[[STALE_KNOWLEDGE]]') return <StaleVsOnline key={key} />;
    if (trimmedLine === '[[ALIGNMENT_GRAPH]]') return <AlignmentGraph key={key} />;
    if (trimmedLine === '[[NASH_EQUILIBRIUM]]') return <NashEquilibriumMatrix key={key} />;
    if (trimmedLine === '[[DRONE_SWARM]]') return <DroneSwarm key={key} />;
    if (trimmedLine === '[[DPS_VISUAL]]') return <DPSVisual key={key} />;
    if (trimmedLine === '[[BITS_VS_ATOMS]]') return <BitsVsAtoms key={key} />;
    if (trimmedLine === '[[FEEDBACK_LOOP]]') return <FeedbackLoop key={key} />;
    if (trimmedLine === '[[MARKET_BIFURCATION]]') return <MarketBifurcation key={key} />;

    // Display Math $$...$$
    if (trimmedLine.startsWith('$$') && trimmedLine.endsWith('$$')) {
        const math = trimmedLine.slice(2, -2).trim();
        return (
            <div key={key} className="my-8 overflow-x-auto flex justify-center">
                <KatexRenderer expression={math} displayMode={true} />
            </div>
        );
    }

    if (trimmedLine.startsWith('### ')) {
      return <h4 key={key} className="text-lg font-bold mt-8 mb-3 text-text-primary tracking-tight">{trimmedLine.substring(4)}</h4>;
    }
    if (trimmedLine.startsWith('## ')) {
      return <h3 key={key} className="text-xl font-bold mt-10 mb-4 text-text-primary tracking-tight">{trimmedLine.substring(3)}</h3>;
    }
    if (trimmedLine.startsWith('# ')) {
      return <h2 key={key} className="text-2xl font-bold mt-12 mb-6 text-text-primary tracking-tight">{trimmedLine.substring(2)}</h2>;
    }

    if (trimmedLine === '---') {
      return <hr key={key} className="my-8 border-border" />;
    }

    if (trimmedLine.startsWith('• ') || trimmedLine.startsWith('- ') || /^\d+\.\s/.test(trimmedLine)) {
      const content = trimmedLine.replace(/^(• |- |\d+\.\s)/, '');
      const parts = content.split(/(\*\*.*?\*\*)/g).filter(Boolean);
      return (
        <div key={key} className="flex items-start my-3 pl-1">
          <span className="text-text-secondary mr-3 mt-1 select-none">&#8226;</span>
          <p className="flex-1 text-text-secondary leading-relaxed">
            {parts.map((part, i) =>
              part.startsWith('**') && part.endsWith('**') ?
              <strong key={i} className="text-text-primary font-semibold">{part.slice(2, -2)}</strong> :
              part
            )}
          </p>
        </div>
      );
    }

    // Handle inline math within paragraphs: $...$
    // We use a more complex split to handle **bold** and $math$
    const parts = trimmedLine.split(/(\*\*.*?\*\*|\$.*?\$)/g).filter(Boolean);

    return (
      <p key={key} className="text-text-secondary leading-relaxed my-4">
        {parts.map((part, i) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={i} className="text-text-primary font-semibold">{part.slice(2, -2)}</strong>;
          }
          if (part.startsWith('$') && part.endsWith('$')) {
             const math = part.slice(1, -1);
             return <KatexRenderer key={i} expression={math} />;
          }
          return <React.Fragment key={i}>{part}</React.Fragment>;
        })}
      </p>
    );
  });
};


